"""Синтетические тестовые данные для инструмента «Доходность капитала».
ВСЁ ВЫДУМАНО: товары «Тест …», цены и остатки подобраны так, чтобы проверить все вердикты
(развивать / держать / выводить / нет остатка) и проверку входа на битых файлах.
Запуск: python make_test_data.py  → папки синтетика/ и битые/ рядом со скриптом."""
from pathlib import Path
import random
import pandas as pd

HERE = Path(__file__).resolve().parent
random.seed(7)
COLS = ["Номер поставки", "Предмет", "Код номенклатуры", "Бренд", "Артикул поставщика", "Название", "Баркод",
        "Тип документа", "Обоснование для оплаты", "Дата заказа покупателем", "Дата продажи", "Кол-во",
        "Цена розничная с учетом согласованной скидки", "Вайлдберриз реализовал Товар (Пр)",
        "К перечислению Продавцу за реализованный Товар", "Услуги по доставке товара покупателю",
        "Общая сумма штрафов", "Корректировка Вознаграждения Вайлдберриз (ВВ)",
        "Виды логистики, штрафов и корректировок ВВ", "Хранение", "Удержания", "Операции на приемке",
        "Возмещение издержек по перевозке/по складским операциям с товаром", "Склад", "Srid"]
# артикул: (поставка, nm, продаж за 28 дн, цена, доля к перечислению, логистика/шт, себестоимость/шт, остаток шт)
ITEMS = {
    "Тест крем 50 мл":        (1001, 900001, 200, 1000, 0.66, 60, 300, 150),   # быстрый и маржинальный → развивать
    "Тест шампунь 250 мл":    (1002, 900002, 24, 800, 0.75, 50, 330, 500),    # медленный, средняя маржа → держать
    "Тест маска 100 мл":      (1003, 900003, 4, 900, 0.60, 120, 480, 700),    # почти не продаётся → выводить
    "Тест бальзам 30 мл":     (1004, 900004, 60, 600, 0.65, 55, 200, None),   # нет в остатках → нет данных / ТЕСТ
    "Тест сыворотка 15 мл":   (1005, 900005, 0, 1500, 0.65, 70, 700, 40),     # только остаток, продаж нет → «нет продаж»
    "Тест тоник 200 мл":      (1006, 900006, 120, 900, 0.70, 50, 250, 900),   # доходный, но запас огромный → сократить закупку
}


def rows_for(week_start, days=14):
    rows = []
    for art, (sup, nm, sold, price, share, logi, cogs, stock) in ITEMS.items():
        n = sold // 2
        for i in range(n):
            d = week_start + pd.Timedelta(days=random.randrange(days))
            srid = f"t{nm}{week_start:%m%d}{i}"
            base = {"Номер поставки": sup, "Код номенклатуры": nm, "Бренд": "ТестБренд", "Артикул поставщика": art,
                    "Название": art, "Дата продажи": d, "Склад": "Тестовый склад", "Srid": srid}
            rows.append({**base, "Тип документа": "Продажа", "Обоснование для оплаты": "Продажа", "Кол-во": 1,
                         "Цена розничная с учетом согласованной скидки": price,
                         "Вайлдберриз реализовал Товар (Пр)": price * 0.7,
                         "К перечислению Продавцу за реализованный Товар": round(price * share, 2)})
            rows.append({**base, "Обоснование для оплаты": "Логистика", "Кол-во": 0,
                         "Услуги по доставке товара покупателю": logi})
    end = week_start + pd.Timedelta(days=days - 1)
    rows.append({"Обоснование для оплаты": "Хранение", "Хранение": 3500, "Дата продажи": end, "Srid": "st" + f"{end:%m%d}"})
    rows.append({"Обоснование для оплаты": "Удержание", "Удержания": 9000, "Дата продажи": end, "Srid": "ad" + f"{end:%m%d}",
                 "Виды логистики, штрафов и корректировок ВВ": "Оказание услуг «WB Продвижение», документ №1"})
    rows.append({"Обоснование для оплаты": "Штраф", "Общая сумма штрафов": 500, "Дата продажи": end, "Srid": "pn" + f"{end:%m%d}",
                 "Артикул поставщика": "Тест маска 100 мл", "Код номенклатуры": 900003,
                 "Виды логистики, штрафов и корректировок ВВ": "Штраф за неправильную упаковку товара"})
    return pd.DataFrame(rows, columns=COLS)


def main():
    syn, bad = HERE / "синтетика", HERE / "битые"
    syn.mkdir(exist_ok=True)
    bad.mkdir(exist_ok=True)
    w1, w2 = pd.Timestamp("2026-03-02"), pd.Timestamp("2026-03-16")
    d1, d2 = rows_for(w1), rows_for(w2)
    d1.to_excel(syn / "Еженедельный детализированный отчет №T001_000000.xlsx", index=False)
    d2.to_excel(syn / "Еженедельный детализированный отчет №T002_000000.xlsx", index=False)
    cat = pd.DataFrame([{"Номер поставки": v[0], "Название товара": k, "Себестоимость": v[6], "Кол-во в поставке": 500}
                        for k, v in ITEMS.items()])
    with pd.ExcelWriter(syn / "каталог-себестоимости-тест.xlsx") as w:
        cat.to_excel(w, sheet_name="Каталог (себестоимость)", index=False)
    # остатки: 3 места хранения, 2 даты. WB — два снимка (15.03 и 29.03), «Склад Москва» — два снимка
    # в одном файле (колонка «Дата»), «Склад Подольск» — одна дата, отдельной таблицей справа на том же листе,
    # что и WB-снимок 29.03. Под WB-таблицей — блок без заголовка (должен уйти в предупреждения).
    def wb_table(share):
        return pd.DataFrame([{"Бренд": "ТестБренд", "Артикул продавца": k, "В пути до получателей": 5,
                              "В пути возвраты на склад WB": 1, "Всего находится на складах": round(v[7] * share)}
                             for k, v in ITEMS.items() if v[7] is not None])
    st = wb_table(0.5)
    wb_table(0.6).to_excel(syn / "остатки-WB-2026-03-15.xlsx", index=False)
    with pd.ExcelWriter(syn / "форма-остатков-2026-03-29.xlsx") as w:
        wb29 = wb_table(0.4)
        wb29.to_excel(w, sheet_name="Остатки", index=False, startrow=0, startcol=0)
        pd.DataFrame([["Тест крем 50 мл", None, None, 999]]).to_excel(w, sheet_name="Остатки", index=False,
                                                                      header=False, startrow=len(wb29) + 3, startcol=1)
        pod = pd.DataFrame([{"Код": i, "Наименование": k, "Остаток": round((v[7] or 0) * 0.3), "Склад Подольск": round((v[7] or 0) * 0.3)}
                            for i, (k, v) in enumerate(ITEMS.items()) if v[7]])
        pod.to_excel(w, sheet_name="Остатки", index=False, startrow=0, startcol=8)
    msk = []
    for d, share in (("15.03.2026", 0.2), ("29.03.2026", 0.1)):
        msk += [{"Дата": d, "Склад": "Склад Москва", "Артикул поставщика": k, "Остаток, шт": round(v[7] * share)}
                for k, v in ITEMS.items() if v[7]]
    pd.DataFrame(msk).to_excel(syn / "учёт-своего-склада.xlsx", index=False)
    # ожидаемо по артикулу: WB (0.6+0.4)/2 = 0.5 + в пути 6; Подольск 0.3; Москва (0.2+0.1)/2 = 0.15 → 0.95 × остаток + 6
    # битые: в детализации нет «Хранение» и «Srid»; в остатках нет количества; в каталоге нет цены
    d1.drop(columns=["Хранение", "Srid"]).to_excel(bad / "Еженедельный детализированный отчет №T003_000000.xlsx", index=False)
    st.drop(columns=["Всего находится на складах", "В пути до получателей", "В пути возвраты на склад WB"]).to_excel(
        bad / "остатки-без-количества.xlsx", index=False)
    with pd.ExcelWriter(bad / "каталог-без-цены.xlsx") as w:
        cat.drop(columns=["Себестоимость"]).to_excel(w, sheet_name="Каталог (себестоимость)", index=False)
    print("готово:", syn, bad)


if __name__ == "__main__":
    main()
